<?php
 namespace Pterodactyl\Services\Dezerx\ServerCreate; use Pterodactyl\Models\Node; use Illuminate\Support\Facades\DB; class NodeCapacity { private const SANE_MAX = 9999; public function forLocations(array $locations, ?array $resources = null): array { if ($locations === []) { return []; } $nodes = Node::query() ->select('id', 'location_id', 'name', 'memory', 'disk', 'memory_overallocate', 'disk_overallocate') ->where('public', 1) ->whereIn('location_id', array_map('intval', $locations)) ->orderBy('id') ->get(); if ($nodes->isEmpty()) { return []; } $ids = $nodes->pluck('id')->map(fn ($id) => (int) $id)->all(); $used = $this->used($ids); $ports = $this->freePorts($ids); $issued = $this->issued($ids); $resources ??= ServerCreate::resources(); $limits = ServerCreate::nodeLimits(); $out = []; foreach ($nodes as $node) { $id = (int) $node->id; $usage = $used[$id] ?? ['servers' => 0, 'memory' => 0, 'disk' => 0]; $free = (int) ($ports[$id] ?? 0); $room = min( $this->fits((int) $node->memory, (float) $node->memory_overallocate, $usage['memory'], $resources['memory']), $this->fits((int) $node->disk, (float) $node->disk_overallocate, $usage['disk'], $resources['disk']), $free, ); $limit = (int) ($limits[$id] ?? 0); $taken = (int) ($issued[$id] ?? 0); if ($limit > 0) { $room = min($room, max(0, $limit - $taken)); } $room = max(0, $room); $out[$id] = [ 'id' => $id, 'location' => (int) $node->location_id, 'name' => (string) $node->name, 'slots' => $room, 'total' => $room + $taken, 'servers' => $usage['servers'], 'free' => $free, ]; } return $out; } public function byLocation(array $locations): array { $blank = ['room' => false, 'slots' => 0, 'total' => 0, 'servers' => 0, 'node' => '']; $out = []; foreach ($locations as $location) { $out[(int) $location] = $blank; } foreach ($this->forLocations($locations) as $node) { $entry = $out[$node['location']] ?? $blank; $entry['slots'] += $node['slots']; $entry['total'] += $node['total']; $entry['servers'] += $node['servers']; $entry['room'] = $entry['room'] || $node['slots'] > 0; $entry['node'] = $entry['node'] === '' ? $node['name'] : $entry['node']; $out[$node['location']] = $entry; } return $out; } public function viableIn(int $location, ?array $resources = null): array { $nodes = array_filter( $this->forLocations([$location], $resources), fn (array $node) => $node['slots'] > 0 && $node['location'] === $location, ); usort($nodes, fn (array $a, array $b) => $b['slots'] <=> $a['slots']); return array_map(fn (array $node) => $node['id'], $nodes); } private function fits(int $capacity, float $overallocate, int $used, int $wanted): int { if ($wanted <= 0) { return self::SANE_MAX; } $ceiling = (int) floor($capacity * (1 + ($overallocate / 100))); return (int) floor(max(0, $ceiling - $used) / $wanted); } private function used(array $nodes): array { return DB::table('servers') ->selectRaw('node_id, COUNT(*) as servers, IFNULL(SUM(memory), 0) as memory, IFNULL(SUM(disk), 0) as disk') ->whereIn('node_id', $nodes) ->groupBy('node_id') ->get() ->mapWithKeys(fn ($row) => [(int) $row->node_id => [ 'servers' => (int) $row->servers, 'memory' => (int) $row->memory, 'disk' => (int) $row->disk, ]]) ->all(); } private function freePorts(array $nodes): array { return DB::table('allocations') ->selectRaw('node_id, COUNT(*) as ports') ->whereNull('server_id') ->whereIn('node_id', $nodes) ->groupBy('node_id') ->pluck('ports', 'node_id') ->map(fn ($count) => (int) $count) ->all(); } private function issued(array $nodes): array { return DB::table('dezerx_free_servers') ->join('servers', 'servers.id', '=', 'dezerx_free_servers.server_id') ->selectRaw('servers.node_id as node_id, COUNT(*) as issued') ->whereIn('servers.node_id', $nodes) ->groupBy('servers.node_id') ->pluck('issued', 'node_id') ->map(fn ($count) => (int) $count) ->all(); } } 